using System;
using System.IO;
using UnityEngine;
using UnityEditor;
namespace MaritimeLegend.Editor {
public static class PixelPorts {
static Texture2D canvas; static Color outline=new Color32(37,43,44,255);static System.Random rng;
static string CityArtPath(int id){var c=JsonUtility.FromJson<MaritimeLegend.Domain.Catalog>(Resources.Load<TextAsset>("Data/catalog").text);string folder="Assets/Cities/"+c.ports[id].cityKey+"/Art";Directory.CreateDirectory(folder);return folder+"/"+c.ports[id].cityKey+".png";}
static void Rect(int x,int y,int w,int h,Color c){for(int j=Math.Max(0,y);j<Math.Min(360,y+h);j++)for(int i=Math.Max(0,x);i<Math.Min(640,x+w);i++)canvas.SetPixel(i,359-j,c);}
static Color C(int r,int g,int b){return new Color32((byte)r,(byte)g,(byte)b,255);}
[MenuItem("Maritime Legend/Generate pixel ports")]
public static void Generate(){for(int port=0;port<8;port++){rng=new System.Random(2519+port);canvas=new Texture2D(640,360,TextureFormat.RGB24,false);Color sea=C(48,105,117),stone=new[]{C(219,190,139),C(205,164,109),C(206,192,163),C(228,203,151),C(205,181,148),C(197,165,115),C(178,166,112),C(183,182,154)}[port];Color roof=new[]{C(145,72,50),C(158,75,47),C(132,68,51),C(171,135,70),C(90,118,112),C(162,83,55),C(119,95,53),C(56,88,98)}[port];Rect(0,0,640,360,stone);for(int y=0;y<130;y++)Rect(0,y,640,1,Color.Lerp(C(118,157,169),C(202,205,172),y/130f));for(int k=0;k<25;k++){int x=rng.Next(640),y=rng.Next(10,90);Rect(x,y,rng.Next(25,85),3,C(208,213,190));}for(int x=0;x<640;x+=8){int h=8+(int)(Math.Sin(x*.04+port)*8);Rect(x,110-h,8,h+20,C(95,123,112));}Rect(0,130,640,150,sea);for(int k=0;k<150;k++){int x=rng.Next(640),y=rng.Next(132,275);Rect(x,y,rng.Next(4,22),1,C(82,143,146));}Rect(0,210,640,150,stone);for(int y=218;y<360;y+=10)for(int x=(y%20==0?0:8);x<640;x+=18){Rect(x,y,16,1,stone*.88f);Rect(x,y,1,9,stone*.92f);}Rect(0,280,640,17,C(83,60,43));for(int x=0;x<640;x+=13){Rect(x,281,1,15,C(144,103,64));}Rect(415,190,135,15,C(86,61,44));for(int x=425;x<555;x+=28){Rect(x,190,5,40,C(65,51,40));Rect(x-1,187,7,4,C(152,114,75));}Building(70,144,90,85,roof,stone,port);Building(215,108,95,105,roof,stone,port);Building(335,83,85,115,roof,stone,port);Building(475,130,80,80,roof,stone,port);Building(145,239,65,43,roof,stone,port);for(int k=0;k<12;k++){int x=rng.Next(30,610),y=rng.Next(240,278);Rect(x,y,13,10,outline);Rect(x+1,y+1,11,8,C(142,101,58));Rect(x+5,y,2,10,C(81,65,45));}for(int k=0;k<8;k++){int x=25+k*83;Rect(x,315,5,45,C(91,76,45));for(int n=0;n<5;n++)Rect(x-14+n*4,308-n*5,32-n*7,5,C(58,87+port*2,58));}if(port==2){Rect(270,208,50,152,sea);for(int y=214;y<360;y+=9)Rect(280,y,20,1,C(95,148,144));Rect(250,257,90,16,C(133,119,85));}if(port==3||port==4){Rect(420,55,12,118,stone);Rect(417,50,18,6,roof);Rect(421,41,10,10,roof);}if(port==7){for(int k=0;k<3;k++){Rect(530-k*8,87+k*18,25+k*16,5,roof);Rect(537-k*6,92+k*18,12+k*12,13,stone);}}canvas.Apply();string path=CityArtPath(port);File.WriteAllBytes(path,canvas.EncodeToPNG());UnityEngine.Object.DestroyImmediate(canvas);}AssetDatabase.Refresh();for(int i=0;i<8;i++){var importer=(TextureImporter)AssetImporter.GetAtPath("Assets/Resources/Sprites/Ports/port"+i+".png");importer.filterMode=FilterMode.Point;importer.textureCompression=TextureImporterCompression.Uncompressed;importer.mipmapEnabled=false;importer.SaveAndReimport();}}
static void Building(int x,int y,int w,int h,Color roof,Color stone,int port){Rect(x+6,y+h-5,w+8,14,C(92,89,65));Rect(x,y,w,h,outline);Rect(x+3,y+3,w-6,h-6,stone*.87f);Rect(x+5,y+5,w-10,h-10,stone);for(int k=0;k<25;k++){int left=x-k/2;int width=w+k;Rect(left,y-k,width,1,outline);Rect(left+2,y-k,width-4,1,roof*(.8f+k*.008f));}if(port==3||port==4){Rect(x-2,y-25,w+4,7,roof);Rect(x+8,y-32,w-16,8,roof);}if(port==7){Rect(x-10,y-23,w+20,4,roof);Rect(x-14,y-28,10,5,roof);Rect(x+w+4,y-28,10,5,roof);}Rect(x+w/2-10,y+h-35,20,35,outline);Rect(x+w/2-7,y+h-32,14,32,C(105,76,48));for(int a=x+12;a<x+w-10;a+=26){Rect(a,y+18,14,19,outline);Rect(a+2,y+20,10,15,C(92,120,115));Rect(a+6,y+19,2,18,stone*.7f);}Rect(x+1,y+h-5,w-2,5,stone*.65f);}
}}
